/* owner:bz-v229-custom-channel-select-js */
(function () {
  function ready(fn) {
    if (document.readyState !== 'loading') fn();
    else fn();
  }

  ready(function () {
    var root = document.getElementById('borzilov-lp');
    if (!root || root.dataset.bz229ChannelSelectReady === '1') return;
    root.dataset.bz229ChannelSelectReady = '1';

    var select = root.querySelector('[data-bz-channel-select]');
    if (!select) return;

    var trigger = select.querySelector('[data-bz-channel-trigger]');
    var label = select.querySelector('[data-bz-channel-label]');
    var menu = select.querySelector('[data-bz-channel-menu]');
    var input = select.querySelector('input[name="channel"]');
    var options = Array.prototype.slice.call(select.querySelectorAll('[data-bz-channel-option]'));
    var questionForm = select.closest('form');
    var contactInput = questionForm && questionForm.elements ? questionForm.elements.contact : null;
    if (!trigger || !label || !menu || !input || !options.length) return;

    function syncContactMode(value) {
      if (!contactInput) return;
      var phoneMode = value === 'max' || value === 'phone' || value === 'whatsapp';
      var fieldLabel = contactInput.closest('.bz-mobile-field');
      if (fieldLabel && fieldLabel.firstChild && fieldLabel.firstChild.nodeType === 3) fieldLabel.firstChild.nodeValue = (phoneMode ? 'Телефон' : 'Контакт') + '\n';
      if (value === 'telegram') contactInput.placeholder = '@username или телефон';
      else if (phoneMode) contactInput.placeholder = '+7 999 123-45-67';
      else contactInput.placeholder = '@username или телефон';
      contactInput.setAttribute('inputmode', phoneMode ? 'tel' : 'text');
      contactInput.setAttribute('autocomplete', 'off');
    }

    function isOpen() { return trigger.getAttribute('aria-expanded') === 'true'; }

    function close(focusTrigger) {
      trigger.setAttribute('aria-expanded', 'false');
      menu.hidden = true;
      if (focusTrigger) trigger.focus();
    }

    function open() {
      trigger.setAttribute('aria-expanded', 'true');
      menu.hidden = false;
      var selected = options.find(function (option) { return option.getAttribute('aria-selected') === 'true'; });
      (selected || options[0]).focus();
    }

    function choose(option) {
      var value = option.getAttribute('data-bz-channel-option') || '';
      input.value = value;
      label.textContent = option.textContent.trim();
      input.removeAttribute('aria-invalid');
      trigger.removeAttribute('aria-invalid');
      options.forEach(function (item) {
        item.setAttribute('aria-selected', item === option ? 'true' : 'false');
      });
      syncContactMode(value);
      close(true);
    }

    trigger.addEventListener('click', function () {
      if (isOpen()) close(false);
      else open();
    });

    options.forEach(function (option, index) {
      option.setAttribute('aria-selected', 'false');
      option.addEventListener('click', function () { choose(option); });
      option.addEventListener('keydown', function (event) {
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
          event.preventDefault();
          var direction = event.key === 'ArrowDown' ? 1 : -1;
          options[(index + direction + options.length) % options.length].focus();
        } else if (event.key === 'Home') {
          event.preventDefault();
          options[0].focus();
        } else if (event.key === 'End') {
          event.preventDefault();
          options[options.length - 1].focus();
        } else if (event.key === 'Escape') {
          event.preventDefault();
          close(true);
        }
      });
    });

    document.addEventListener('pointerdown', function (event) {
      if (isOpen() && !select.contains(event.target)) close(false);
    }, true);

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && isOpen()) {
        event.preventDefault();
        close(true);
      }
    }, true);
  });
})();
;

/* owner:bz-v230-question-form-ux-controller-js */
(function () {
  function ready(fn) {
    if (document.readyState !== 'loading') fn();
    else fn();
  }

  ready(function () {
    var root = document.getElementById('borzilov-lp');
    if (!root || root.dataset.bz230ActionSheetsReady === '1') return;
    root.dataset.bz230ActionSheetsReady = '1';

    var sheet = root.querySelector('.bz-mobile-stack-sheet');
    var sheetBody = root.querySelector('.bz-mobile-stack-sheet__body');
    var closeButton = root.querySelector('.bz-mobile-stack-sheet__close');
    var menuTrigger = root.querySelector('.bz-mobile-nav-trigger');
    var questionForm = root.querySelector('[data-bz-mobile-stack-form="question"]');
    var successDetail = root.querySelector('[data-bz-question-success-detail]');
    var returnButton = root.querySelector('[data-bz-question-return]');

    /* Session draft: no network calls, no polling. */
    var draftKey = 'bz-mobile-question-draft-v1';
    function readDraft() {
      try { return JSON.parse(sessionStorage.getItem(draftKey) || '{}') || {}; }
      catch (_) { return {}; }
    }
    function writeDraft() {
      if (!questionForm) return;
      var data = {
        question: String((questionForm.elements.question || {}).value || ''),
        channel: String((questionForm.elements.channel || {}).value || ''),
        contact: String((questionForm.elements.contact || {}).value || '')
      };
      try { sessionStorage.setItem(draftKey, JSON.stringify(data)); } catch (_) {}
    }
    function restoreDraft() {
      if (!questionForm) return;
      var draft = readDraft();
      ['question', 'channel', 'contact'].forEach(function (name) {
        if (questionForm.elements[name] && draft[name]) questionForm.elements[name].value = draft[name];
      });
      if (draft.channel) {
        var option = root.querySelector('[data-bz-channel-option="' + draft.channel.replace(/"/g, '') + '"]');
        var label = root.querySelector('[data-bz-channel-label]');
        if (option && label) {
          label.textContent = option.textContent.trim();
          root.querySelectorAll('[data-bz-channel-option]').forEach(function (item) {
            item.setAttribute('aria-selected', item === option ? 'true' : 'false');
          });
          var contactInput = questionForm.elements.contact;
          if (contactInput) {
            var phoneMode = draft.channel === 'max' || draft.channel === 'phone' || draft.channel === 'whatsapp';
            var fieldLabel = contactInput.closest('.bz-mobile-field');
            if (fieldLabel && fieldLabel.firstChild && fieldLabel.firstChild.nodeType === 3) fieldLabel.firstChild.nodeValue = (phoneMode ? 'Телефон' : 'Контакт') + '\n';
            contactInput.placeholder = draft.channel === 'telegram' ? '@username или телефон' : (phoneMode ? '+7 999 123-45-67' : '@username или телефон');
            contactInput.setAttribute('inputmode', phoneMode ? 'tel' : 'text');
            contactInput.setAttribute('autocomplete', 'off');
          }
        }
      }
    }

    function maskPhone(value) {
      var digits = String(value || '').replace(/\D/g, '');
      if (digits.length < 4) return String(value || '').trim();
      var tail = digits.slice(-4);
      return (digits[0] === '7' ? '+7 ' : '') + '••• •••-' + tail.slice(0, 2) + '-' + tail.slice(2);
    }
    function successText(channel, contact) {
      var names = { telegram: 'Telegram', max: 'MAX', whatsapp: 'WhatsApp', vk: 'ВКонтакте', phone: 'телефону' };
      var name = names[channel] || 'указанном канале';
      if (channel === 'phone') return 'Ответим по номеру: ' + maskPhone(contact);
      return 'Ответим в ' + name + (contact ? ': ' + contact : '.');
    }

    if (questionForm) {
      restoreDraft();
      questionForm.addEventListener('input', writeDraft, { passive: true });
      questionForm.addEventListener('change', writeDraft, { passive: true });
      questionForm.addEventListener('submit', function () {
        var channel = String((questionForm.elements.channel || {}).value || '').trim();
        var contact = String((questionForm.elements.contact || {}).value || '').trim();
        writeDraft();
        if (successDetail && channel && contact) successDetail.textContent = successText(channel, contact);
      }, true);
    }

    /* Return means exactly that: close the action sheet, then close the menu and
       unlock the page at the same saved scroll position. */
    if (returnButton && menuTrigger) {
      returnButton.addEventListener('click', function () {
        window.setTimeout(function () {
          if (root.classList.contains('bz-mobile-nav-open')) menuTrigger.click();
        }, 24);
      });
    }

  });
})();
;

/* owner:bz-v2048-production-lead-delivery */
(function(){
  'use strict';

  var ENDPOINT='https://ilaborzilov0-netizen-metod-payment-test-0305.twc1.net/api/leads';
  var FORM_SELECTOR=[
    '[data-bz-footer-form]',
    '[data-bzc-application-form]',
    '[data-bzc-contact-form]',
    '[data-bz-mobile-stack-form="question"]',
    '[data-bz-mobile-stack-form="application"]',
    '[data-bz-inline-application-form]'
  ].join(',');
  var openedAt=Date.now();

  function text(value,max){
    return String(value==null?'':value).trim().slice(0,max||500);
  }

  function utm(){
    var params=new URLSearchParams(location.search);
    return {
      source:text(params.get('utm_source'),120),
      medium:text(params.get('utm_medium'),120),
      campaign:text(params.get('utm_campaign'),180),
      content:text(params.get('utm_content'),180),
      term:text(params.get('utm_term'),180)
    };
  }

  function formType(form){
    if(form.matches('[data-bz-footer-form]'))return 'footer_application';
    if(form.matches('[data-bzc-application-form]'))return 'commercial_application';
    if(form.matches('[data-bz-mobile-stack-form="question"]'))return 'mobile_question';
    /* Backend contract: every application form uses the accepted application type.
       The exact placement is preserved separately in payload.source. */
    if(form.matches('[data-bz-mobile-stack-form="application"]'))return 'commercial_application';
    if(form.matches('[data-bz-inline-application-form]'))return 'commercial_application';
    if(form.matches('[data-bzc-contact-form]')){
      var target=text((form.elements.contact_target||{}).value,50);
      if(target==='call'||target==='personal-call')return 'callback_request';
      if(target==='ilya')return 'personal_contact';
      return 'commercial_contact';
    }
    return '';
  }

  function source(form){
    if(form.matches('[data-bz-footer-form]'))return 'footer-form';
    if(form.matches('[data-bz-mobile-stack-form="question"]'))return 'mobile-menu-question';
    if(form.matches('[data-bz-mobile-stack-form="application"]'))return text(form.getAttribute('data-bz-application-source')||'mobile-application',100);
    if(form.matches('[data-bz-inline-application-form]'))return text(form.getAttribute('data-bz-application-source')||'meaning-inline-application',100);
    var layer=document.getElementById('bz-commercial-layer');
    var state=window.BZCommercialPaymentPrototype&&window.BZCommercialPaymentPrototype.state;
    return text((state&&state.source)||form.getAttribute('data-source')||(layer&&layer.dataset.source)||'commercial-drawer',100);
  }

  function payload(form){
    var fd=new FormData(form);
    var type=formType(form);
    return {
      formType:type,
      name:text(fd.get('name'),100),
      contactType:text(fd.get('contact_type')||fd.get('channel'),30),
      contact:text(fd.get('contact'),160),
      message:text(fd.get('comment')||fd.get('question'),1500),
      plan:text(fd.get('tariff'),60),
      price:text(fd.get('price'),60),
      startDate:text(fd.get('start_date'),60),
      preferredTime:text(fd.get('preferred_time'),120),
      source:source(form),
      sourceUrl:location.href.slice(0,500),
      referrer:document.referrer.slice(0,500),
      utm:utm(),
      openedAt:openedAt,
      website:text(fd.get('website'),120)
    };
  }

  function requiredValid(form){
    var invalid=Array.prototype.find.call(form.querySelectorAll('[required]'),function(field){
      return !text(field.value,500);
    });
    if(!invalid)return true;
    invalid.setAttribute('aria-invalid','true');
    var host=invalid.closest('[data-bzc-field],[data-bz-footer-field],[data-bz-inline-field],.bz-mobile-field');
    if(host)host.classList.add('is-invalid');
    try{invalid.focus();}catch(_){}
    return false;
  }

  function button(form){
    return form.querySelector('[type="submit"]');
  }

  function setBusy(form,busy){
    var btn=button(form);
    if(!btn)return;
    if(busy){
      btn.dataset.bzLeadOriginal=btn.textContent;
      btn.textContent='Отправляем…';
      btn.disabled=true;
      form.setAttribute('aria-busy','true');
    }else{
      btn.textContent=btn.dataset.bzLeadOriginal||btn.textContent;
      btn.disabled=false;
      form.removeAttribute('aria-busy');
    }
  }

  function showError(form,message){
    var node=form.querySelector('[data-bz-lead-error]');
    if(!node){
      node=document.createElement('p');
      node.setAttribute('data-bz-lead-error','');
      node.setAttribute('role','alert');
      node.style.cssText='margin:10px 0 0;color:#a34132;font-size:12px;line-height:1.4;';
      form.appendChild(node);
    }
    node.textContent=message||'Не удалось отправить заявку. Попробуйте ещё раз.';
  }

  function clearError(form){
    var node=form.querySelector('[data-bz-lead-error]');
    if(node)node.remove();
  }

  function showSuccess(form,data,leadPayload){
    if(form.matches('[data-bz-inline-application-form],[data-bz-mobile-stack-form="application"]')){
      window.BZLastApplicationLead={payload:leadPayload||payload(form),leadId:text(data&&data.leadId,80),submittedAt:Date.now()};
    }
    if(form.matches('[data-bz-footer-form]')){
      var card=form.closest('.bz-footer-form-card');
      if(card)card.classList.add('bz-footer-form-is-success');
      return;
    }

    if(form.matches('[data-bzc-application-form],[data-bzc-contact-form]')){
      var api=window.BZCommercialPaymentPrototype;
      if(api&&typeof api.setView==='function')api.setView('application-success');
      return;
    }

    if(form.matches('[data-bz-mobile-stack-form="question"]')){
      var root=document.getElementById('borzilov-lp');
      var sheet=root&&root.querySelector('.bz-mobile-stack-sheet');
      var views=root&&root.querySelectorAll('[data-bz-stack-view]');
      if(views)views.forEach(function(view){view.classList.toggle('is-active',view.getAttribute('data-bz-stack-view')==='question-success');});
      if(sheet)sheet.setAttribute('data-bz-stack-current-view','question-success');
      var detail=root&&root.querySelector('[data-bz-question-success-detail]');
      if(detail)detail.textContent='Вопрос отправлен. Ответим в указанном канале.';
    }

    if(form.matches('[data-bz-mobile-stack-form="application"]')){
      var root=document.getElementById('borzilov-lp');
      var sheet=root&&root.querySelector('.bz-mobile-stack-sheet');
      var views=root&&root.querySelectorAll('[data-bz-stack-view]');
      if(views)views.forEach(function(view){view.classList.toggle('is-active',view.getAttribute('data-bz-stack-view')==='application-success');});
      if(sheet)sheet.setAttribute('data-bz-stack-current-view','application-success');
      var detail=root&&root.querySelector('[data-bz-application-success-detail]');
      if(detail){var applicationSource=form.getAttribute('data-bz-application-source')||'';detail.textContent=applicationSource==='author-situation'?'Описание отправлено. Я посмотрю ситуацию и отвечу по указанному контакту.':'Я свяжусь с вами по указанному контакту.';}
    }

    if(form.matches('[data-bz-inline-application-form]')){
      var owner=form.closest('[data-bz-application-owner]');
      var success=owner&&owner.querySelector('[data-bz-inline-application-success]');
      var panel=owner&&owner.querySelector('[data-bz-inline-application-panel]');
      var copy=owner&&owner.querySelector('[data-bz-inline-application-success-copy]');
      if(copy)copy.textContent='Я свяжусь с вами по указанному контакту.';
      if(owner)owner.classList.add('is-success');
      if(panel)panel.hidden=false;
      if(success)success.hidden=false;
      if(form)form.hidden=true;
      if(window.BZInlineApplications&&typeof window.BZInlineApplications.refresh==='function')window.requestAnimationFrame(function(){window.BZInlineApplications.refresh(owner);});
      return;
    }
  }

  async function send(form){
    clearError(form);
    if(!requiredValid(form))return;
    setBusy(form,true);
    try{
      var leadPayload=payload(form);
      var response=await fetch(ENDPOINT,{
        method:'POST',
        headers:{'Content-Type':'application/json','Accept':'application/json'},
        body:JSON.stringify(leadPayload)
      });
      var data=await response.json().catch(function(){return {};});
      if(!response.ok||data.ok!==true)throw new Error(data.error||'Не удалось отправить заявку.');
      form.dataset.bzLeadId=text(data.leadId,80);
      showSuccess(form,data,leadPayload);
      try{form.reset();}catch(_){}
    }catch(error){
      showError(form,error&&error.message);
    }finally{
      setBusy(form,false);
    }
  }

  document.addEventListener('submit',function(event){
    var form=event.target&&event.target.closest&&event.target.closest(FORM_SELECTOR);
    if(!form)return;
    event.preventDefault();
    event.stopPropagation();
    if(typeof event.stopImmediatePropagation==='function')event.stopImmediatePropagation();
    send(form);
  },true);
})();
;
